const t={hostControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Gestisci l'host Linux della stampante - controlla il suo stato, gestisci i servizi in background, libera spazio su disco e modifica le impostazioni di sistema (ora, lingua, hostname, rete, alimentazione)."}},view:{monitor:{t:0,b:{t:2,i:[{t:3}],s:"Monitor"}},services:{t:0,b:{t:2,i:[{t:3}],s:"Servizi"}},cleanup:{t:0,b:{t:2,i:[{t:3}],s:"Pulizia"}},system:{t:0,b:{t:2,i:[{t:3}],s:"Sistema"}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Aiuto"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Informazioni su Host Control"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Chiudi"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Come leggere"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Leggi a colpo d'occhio le schede di temperatura CPU, memoria, disco e rete."}},{t:0,b:{t:2,i:[{t:3}],s:"Osserva la tabella dei processi principali per vedere cosa sta usando la CPU in questo momento."}},{t:0,b:{t:2,i:[{t:3}],s:"Lascia attivo l'aggiornamento automatico per una vista live, oppure disattivalo e aggiorna manualmente."}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Termini usati qui"}}},monitor:{title:{t:0,b:{t:2,i:[{t:3}],s:"Leggere il monitor"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Qui è tutto in sola lettura. Le barre diventano ambra oltre il 75% e rosse oltre il 90%. La temperatura della CPU diventa ambra a 70 °C e rossa a 80 °C. L'avviso di throttling appare solo sulle schede che lo segnalano (principalmente Raspberry Pi)."}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:"Gestire i servizi"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ogni riga è un servizio systemd. Clicca su uno per avviarlo/arrestarlo/riavviarlo, abilitarlo/disabilitarlo all'avvio, mascherarlo, leggerne il log o - per i servizi installati da te - eliminarne il file unit. Arrestare o disabilitare un servizio richiede una conferma digitata o con un tocco. I servizi critici e protetti sono contrassegnati; quelli protetti (come SSH e questo pannello) non possono essere arrestati, per evitare di bloccarti fuori."}}},cleanup:{title:{t:0,b:{t:2,i:[{t:3}],s:"Liberare spazio su disco"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ogni voce viene prima scansionata per mostrare quanto spazio libererebbe. Spunta quelle da eliminare e conferma. Vengono offerti solo dati rigenerabili - la cache dei download di apt, il vecchio journal di systemd, ~/.cache, i tuoi vecchi file in /tmp e i log ruotati (non attivi). I tuoi G-code, timelapse e config non vengono mai toccati."}}},system:{title:{t:0,b:{t:2,i:[{t:3}],s:"Impostazioni di sistema"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Modifica il fuso orario e l'orologio dell'host, la lingua e la tastiera, l'hostname o la rete (DHCP / IP statico), oppure riavvialo/spegnilo. Ogni modifica viene applicata immediatamente. Riavvio e spegnimento sono rifiutati durante una stampa in corso. Cambiare l'IP può interrompere brevemente la connessione a questo pannello."}}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:"DHCP vs IP statico"}},body:{t:0,b:{t:2,i:[{t:3}],s:"DHCP (auto) lascia che il router assegni l'indirizzo automaticamente. Statico (manuale) fissa un indirizzo prestabilito - imposta l'IP, la subnet (CIDR, es. /24), il gateway (di solito il router) e il DNS. Solo IPv4. Cambiare l'indirizzo della connessione che serve questo pannello interromperà la sessione; riconnettiti al nuovo IP. Un indirizzo statico o un gateway errato può rendere la stampante irraggiungibile finché non lo correggi sul dispositivo stesso, perciò le impostazioni sono validate e richiedono una conferma digitata."}}}},glossary:{host:{term:{t:0,b:{t:2,i:[{t:3}],s:"Host"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Il piccolo computer Linux (es. un Raspberry Pi o un BTT CB1) che esegue Klipper, Moonraker e FilaMind - distinto dai microcontroller della stampante."}}},load:{term:{t:0,b:{t:2,i:[{t:3}],s:"Carico medio"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Quanti processi erano in attesa di esecuzione, mediati su 1 / 5 / 15 minuti. In breve: un valore vicino al numero di core indica che la CPU è occupata; molto al di sopra significa che è sovraccarica."}}},swap:{term:{t:0,b:{t:2,i:[{t:3}],s:"Swap"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Spazio su disco usato come overflow quando la RAM si riempie. Un uso intenso dello swap rallenta l'host - segno che è a corto di memoria."}}},throttle:{term:{t:0,b:{t:2,i:[{t:3}],s:"Throttling"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Quando la scheda riduce la velocità per proteggersi - di solito a causa di un'alimentazione insufficiente (sottotensione) o surriscaldamento. Segnalato principalmente su Raspberry Pi."}}},ntp:{term:{t:0,b:{t:2,i:[{t:3}],s:"NTP / sincronizzazione orologio"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Il Network Time Protocol mantiene preciso l'orologio dell'host. Un orologio non sincronizzato può compromettere timelapse, log e certificati TLS."}}},locale:{term:{t:0,b:{t:2,i:[{t:3}],s:"Locale"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Le impostazioni di lingua e layout di tastiera dell'host, usate dal sistema operativo per testo, date e mappatura tasti della console."}}},service:{term:{t:0,b:{t:2,i:[{t:3}],s:"Servizio (unit)"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Un programma in background gestito da systemd - Klipper, Moonraker, lo streamer della webcam e lo stack di rete funzionano tutti come servizi."}}},enabled:{term:{t:0,b:{t:2,i:[{t:3}],s:"Abilitato / disabilitato"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Se un servizio si avvia automaticamente all'avvio. 'abilitato' parte all'avvio; 'disabilitato' no; 'static' viene avviato solo da un altro servizio."}}},mask:{term:{t:0,b:{t:2,i:[{t:3}],s:"Mask"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Una forma più forte di disabilitazione - il servizio non può essere avviato affatto (nemmeno da un altro servizio) finché non viene smascherato. Usare con cautela."}}}}},monitor:{refresh:{t:0,b:{t:2,i:[{t:3}],s:"Aggiorna"}},autoRefresh:{t:0,b:{t:2,i:[{t:3}],s:"Aggiornamento automatico"}},loading:{t:0,b:{t:2,i:[{t:3}],s:"Lettura dello stato dell'host…"}},host:{t:0,b:{t:2,i:[{t:3}],s:"Host"}},hostname:{t:0,b:{t:2,i:[{t:3}],s:"Hostname"}},distro:{t:0,b:{t:2,i:[{t:3}],s:"OS"}},kernel:{t:0,b:{t:2,i:[{t:3}],s:"Kernel"}},uptime:{t:0,b:{t:2,i:[{t:3}],s:"Uptime"}},cpu:{t:0,b:{t:2,i:[{t:3}],s:"CPU"}},temp:{t:0,b:{t:2,i:[{t:3}],s:"Temperatura"}},load:{t:0,b:{t:2,i:[{t:3}],s:"Carico (1·5·15m)"}},cores:{t:0,b:{t:2,i:[{t:3}],s:"Core"}},throttled:{t:0,b:{t:2,i:[{t:3}],s:"In throttling"}},memory:{t:0,b:{t:2,i:[{t:3}],s:"Memoria"}},ram:{t:0,b:{t:2,i:[{t:3}],s:"RAM"}},swap:{t:0,b:{t:2,i:[{t:3}],s:"Swap"}},disk:{t:0,b:{t:2,i:[{t:3}],s:"Disco"}},network:{t:0,b:{t:2,i:[{t:3}],s:"Rete"}},iface:{t:0,b:{t:2,i:[{t:3}],s:"Interfaccia"}},ip:{t:0,b:{t:2,i:[{t:3}],s:"Indirizzo IP"}},ssid:{t:0,b:{t:2,i:[{t:3}],s:"Wi-Fi"}},signal:{t:0,b:{t:2,i:[{t:3}],s:"Segnale"}},timeLocale:{t:0,b:{t:2,i:[{t:3}],s:"Ora e Locale"}},timezone:{t:0,b:{t:2,i:[{t:3}],s:"Fuso orario"}},ntp:{t:0,b:{t:2,i:[{t:3}],s:"Sincronizzazione orologio"}},synced:{t:0,b:{t:2,i:[{t:3}],s:"Sincronizzato"}},syncing:{t:0,b:{t:2,i:[{t:3}],s:"Sincronizzazione…"}},ntpOff:{t:0,b:{t:2,i:[{t:3}],s:"Off"}},language:{t:0,b:{t:2,i:[{t:3}],s:"Lingua"}},keymap:{t:0,b:{t:2,i:[{t:3}],s:"Mappatura tasti"}},topProcesses:{t:0,b:{t:2,i:[{t:3}],s:"Processi principali"}},command:{t:0,b:{t:2,i:[{t:3}],s:"Comando"}},cpuPct:{t:0,b:{t:2,i:[{t:3}],s:"CPU%"}},memPct:{t:0,b:{t:2,i:[{t:3}],s:"MEM%"}},pid:{t:0,b:{t:2,i:[{t:3}],s:"PID"}}},services:{warning:{t:0,b:{t:2,i:[{t:3}],s:"Arrestare o disabilitare il servizio sbagliato può mettere la stampante offline. I servizi critici sono contrassegnati; quelli protetti non possono essere arrestati."}},search:{t:0,b:{t:2,i:[{t:3}],s:"Cerca servizi…"}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Aggiorna"}},loading:{t:0,b:{t:2,i:[{t:3}],s:"Elenco dei servizi…"}},loadingDetail:{t:0,b:{t:2,i:[{t:3}],s:"Lettura del servizio…"}},loadingLogs:{t:0,b:{t:2,i:[{t:3}],s:"Lettura del log…"}},summary:{t:0,b:{t:2,i:[{t:4,k:"total"},{t:3,v:" servizi · "},{t:4,k:"active"},{t:3,v:" attivi · "},{t:4,k:"failed"},{t:3,v:" falliti"}]}},filter:{all:{t:0,b:{t:2,i:[{t:3}],s:"Tutti"}},active:{t:0,b:{t:2,i:[{t:3}],s:"Attivi"}},inactive:{t:0,b:{t:2,i:[{t:3}],s:"Inattivi"}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Falliti"}},enabled:{t:0,b:{t:2,i:[{t:3}],s:"Abilitati"}}},stateActive:{t:0,b:{t:2,i:[{t:3}],s:"Attivo"}},stateInactive:{t:0,b:{t:2,i:[{t:3}],s:"Inattivo"}},stateFailed:{t:0,b:{t:2,i:[{t:3}],s:"Fallito"}},critical:{t:0,b:{t:2,i:[{t:3}],s:"Critico"}},protected:{t:0,b:{t:2,i:[{t:3}],s:"Protetto"}},state:{t:0,b:{t:2,i:[{t:3}],s:"Stato"}},startup:{t:0,b:{t:2,i:[{t:3}],s:"Avvio"}},unitFile:{t:0,b:{t:2,i:[{t:3}],s:"File unit"}},action:{start:{t:0,b:{t:2,i:[{t:3}],s:"Avvia"}},stop:{t:0,b:{t:2,i:[{t:3}],s:"Arresta"}},restart:{t:0,b:{t:2,i:[{t:3}],s:"Riavvia"}},enable:{t:0,b:{t:2,i:[{t:3}],s:"Abilita"}},disable:{t:0,b:{t:2,i:[{t:3}],s:"Disabilita"}},mask:{t:0,b:{t:2,i:[{t:3}],s:"Maschera"}},unmask:{t:0,b:{t:2,i:[{t:3}],s:"Smaschera"}}},actionOk:{t:0,b:{t:2,i:[{t:4,k:"action"},{t:3,v:" completato."}]}},actionFailed:{t:0,b:{t:2,i:[{t:4,k:"action"},{t:3,v:" fallito."}]}},deleteFailed:{t:0,b:{t:2,i:[{t:3}],s:"Impossibile rimuovere il file unit."}},confirmAction:{t:0,b:{t:2,i:[{t:4,k:"action"},{t:3,v:' "'},{t:4,k:"name"},{t:3,v:'"?'}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:"Sì, procedi"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annulla"}},deleteUnit:{t:0,b:{t:2,i:[{t:3}],s:"Elimina file unit…"}},deletePrompt:{t:0,b:{t:2,i:[{t:3,v:'Questo rimuove definitivamente il file unit. Digita "'},{t:4,k:"name"},{t:3,v:'" per confermare.'}]}},deleteConfirm:{t:0,b:{t:2,i:[{t:3}],s:"Elimina definitivamente"}},deleted:{t:0,b:{t:2,i:[{t:3}],s:"File unit rimosso."}},logs:{t:0,b:{t:2,i:[{t:3}],s:"Log recente"}},noLogs:{t:0,b:{t:2,i:[{t:3}],s:"Nessun output di log."}}},cleanup:{subtitle:{t:0,b:{t:2,i:[{t:3}],s:"Spunta cosa rimuovere, poi pulisci. Solo cache e vecchi log - stampe e config restano al sicuro."}},rescan:{t:0,b:{t:2,i:[{t:3}],s:"Riscansiona"}},scanning:{t:0,b:{t:2,i:[{t:3}],s:"Scansione del disco…"}},na:{t:0,b:{t:2,i:[{t:3}],s:"n/d"}},items:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" file"}]}},freed:{t:0,b:{t:2,i:[{t:3,v:"Liberati "},{t:4,k:"size"},{t:3,v:"."}]}},selectedTotal:{t:0,b:{t:2,i:[{t:3,v:"Selezionati: "},{t:4,k:"size"}]}},clean:{t:0,b:{t:2,i:[{t:3}],s:"Pulisci selezionati"}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:"Eliminare le voci selezionate?"}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:"Sì, pulisci"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annulla"}},running:{t:0,b:{t:2,i:[{t:3}],s:"Pulizia…"}},someFailed:{t:0,b:{t:2,i:[{t:3}],s:"Alcune voci non hanno potuto essere pulite."}},targets:{apt:{label:{t:0,b:{t:2,i:[{t:3}],s:"Cache pacchetti"}},desc:{t:0,b:{t:2,i:[{t:3}],s:"File installer .deb scaricati di cui apt non ha più bisogno."}}},journal:{label:{t:0,b:{t:2,i:[{t:3}],s:"Journal di sistema"}},desc:{t:0,b:{t:2,i:[{t:3}],s:"Vecchi log di systemd - ridotti agli ultimi 50 MB."}}},cache:{label:{t:0,b:{t:2,i:[{t:3}],s:"Cache utente"}},desc:{t:0,b:{t:2,i:[{t:3}],s:"File rigenerabili in ~/.cache (miniature, pip, ecc.)."}}},tmp:{label:{t:0,b:{t:2,i:[{t:3}],s:"File temporanei"}},desc:{t:0,b:{t:2,i:[{t:3}],s:"I tuoi file in /tmp più vecchi di un giorno."}}},logs:{label:{t:0,b:{t:2,i:[{t:3}],s:"Log ruotati"}},desc:{t:0,b:{t:2,i:[{t:3}],s:"Vecchi log Klipper/Moonraker ruotati (il log attivo viene conservato)."}}}}},system:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Lettura delle impostazioni di sistema…"}},done:{t:0,b:{t:2,i:[{t:3}],s:"Fatto."}},apply:{t:0,b:{t:2,i:[{t:3}],s:"Applica"}},timeTitle:{t:0,b:{t:2,i:[{t:3}],s:"Ora e Data"}},timezone:{t:0,b:{t:2,i:[{t:3}],s:"Fuso orario"}},ntp:{t:0,b:{t:2,i:[{t:3}],s:"Imposta l'ora automaticamente (NTP)"}},manualTime:{t:0,b:{t:2,i:[{t:3}],s:"Imposta l'orologio manualmente"}},manualTimeHint:{t:0,b:{t:2,i:[{t:3}],s:"Disattiva l'ora automatica per impostare l'orologio a mano."}},localeTitle:{t:0,b:{t:2,i:[{t:3}],s:"Lingua e Tastiera"}},language:{t:0,b:{t:2,i:[{t:3}],s:"Lingua"}},keymap:{t:0,b:{t:2,i:[{t:3}],s:"Mappatura tasti console"}},hostnameTitle:{t:0,b:{t:2,i:[{t:3}],s:"Hostname"}},hostnameHint:{t:0,b:{t:2,i:[{t:3}],s:"Solo lettere, cifre e trattini. Ha pieno effetto dopo un riavvio."}},powerTitle:{t:0,b:{t:2,i:[{t:3}],s:"Alimentazione"}},powerWarning:{t:0,b:{t:2,i:[{t:3}],s:"Riavvio e spegnimento sono rifiutati durante una stampa in corso."}},reboot:{t:0,b:{t:2,i:[{t:3}],s:"Riavvia"}},shutdown:{t:0,b:{t:2,i:[{t:3}],s:"Spegni"}},confirmReboot:{t:0,b:{t:2,i:[{t:3}],s:"Riavviare l'host ora?"}},confirmShutdown:{t:0,b:{t:2,i:[{t:3}],s:"Spegnere l'host ora?"}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:"Sì"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Annulla"}},needsSetup:{t:0,b:{t:2,i:[{t:3}],s:"Questa azione richiede sudo senza password. Sulla stampante, esegui: sudo bash scripts/install.sh sudoers - poi riprova."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Quella modifica non è stata applicata."}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:"Rete (IPv4)"}},unavailable:{t:0,b:{t:2,i:[{t:3}],s:"La modifica della rete non è disponibile su questo host (NetworkManager non installato)."}},device:{t:0,b:{t:2,i:[{t:3}],s:"Dispositivo"}},method:{t:0,b:{t:2,i:[{t:3}],s:"Metodo IP"}},auto:{t:0,b:{t:2,i:[{t:3}],s:"DHCP (auto)"}},manual:{t:0,b:{t:2,i:[{t:3}],s:"Statico (manuale)"}},address:{t:0,b:{t:2,i:[{t:3}],s:"Indirizzo IP"}},cidr:{t:0,b:{t:2,i:[{t:3}],s:"Subnet (CIDR)"}},gateway:{t:0,b:{t:2,i:[{t:3}],s:"Gateway"}},dns:{t:0,b:{t:2,i:[{t:3}],s:"Server DNS"}},dnsHint:{t:0,b:{t:2,i:[{t:3}],s:"Separati da virgola, es. 1.1.1.1, 8.8.8.8 (opzionale)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"Cambiare l'IP può interrompere questo pannello - potrebbe essere necessario riconnettersi al nuovo indirizzo."}},apply:{t:0,b:{t:2,i:[{t:3}],s:"Applica impostazioni di rete"}},confirmPrompt:{t:0,b:{t:2,i:[{t:3,v:'Questo potrebbe rendere il pannello irraggiungibile. Digita il nome del dispositivo "'},{t:4,k:"device"},{t:3,v:'" per confermare.'}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:"Applica e cambia"}},applyingReconnect:{t:0,b:{t:2,i:[{t:3}],s:"Applicazione… se il pannello smette di rispondere, riconnettiti al nuovo IP della stampante."}}}}}};export{t as default};
